-- Make inhagame_hub_events context check two-valued.
-- A NULL result (e.g. first_reward with NULL target) satisfied the previous CHECK
-- because CHECK only rejects FALSE. Same vocabulary and semantics; NULL now rejects.
alter table public.inhagame_hub_events drop constraint hub_event_context_check;
alter table public.inhagame_hub_events add constraint hub_event_context_check check (coalesce(
(((entry_id IS NULL) AND (((event_type = 'hub_visit'::text) AND (surface = 'home'::text) AND (target IS NULL)) OR ((event_type = 'hub_panel_view'::text) AND (surface = ANY (ARRAY['home'::text, 'ranking'::text, 'friends'::text, 'messages'::text, 'account'::text, 'settings'::text])) AND (target IS NULL)) OR ((event_type = 'hub_game_click'::text) AND (surface = ANY (ARRAY['home'::text, 'ranking'::text, 'account'::text])) AND (target = ANY (ARRAY['classic'::text, 'induckup'::text, 'survival'::text, 'induck-grow'::text]))) OR ((event_type = 'campus_entry_click'::text) AND (surface = 'home'::text) AND (target = 'campus'::text)) OR ((event_type = 'hub_card_impression'::text) AND (surface = 'home'::text) AND (target = ANY (ARRAY['classic'::text, 'induckup'::text, 'survival'::text, 'campus'::text, 'induck-grow'::text]))) OR ((event_type = ANY (ARRAY['campus_boot_ready'::text, 'campus_boot_error'::text])) AND (surface = 'campus'::text) AND (target IS NULL)) OR ((event_type = 'campus_zone_enter'::text) AND (surface = 'campus'::text) AND (target = ANY (ARRAY['C01_GATE'::text, 'C02_MAIN_HALL'::text, 'C03_CENTRAL'::text]))) OR ((event_type = ANY (ARRAY['profile_view'::text, 'profile_edit_open'::text, 'profile_edit_save'::text])) AND (surface = 'profile'::text) AND (target IS NULL)) OR ((event_type = 'profile_game_click'::text) AND (surface = 'profile'::text) AND (target = ANY (ARRAY['classic'::text, 'induckup'::text, 'survival'::text, 'campus'::text, 'induck-grow'::text]))) OR ((event_type = ANY (ARRAY['first_session_start'::text, 'first_move'::text, 'first_zone_arrival'::text, 'first_npc_interaction'::text, 'first_player_encounter'::text, 'world_return'::text])) AND (surface = 'campus'::text) AND (target IS NULL)) OR ((event_type = ANY (ARRAY['first_activity_start'::text, 'first_activity_complete'::text])) AND (surface = 'campus'::text) AND (target = 'inkyung_living'::text)) OR ((event_type = ANY (ARRAY['first_reward'::text, 'core_loop_complete'::text])) AND (surface = 'campus'::text) AND (target = 'first_campus'::text)) OR ((event_type = 'next_discovery_click'::text) AND (surface = 'campus'::text) AND (target = 'main2_back_gate_guide'::text)))) OR ((entry_id IS NOT NULL) AND (event_type = ANY (ARRAY['game_landing'::text, 'game_play_start'::text, 'game_load_error'::text, 'game_first_result'::text, 'game_first_clear'::text, 'game_retry'::text, 'classic_ranked_start'::text])) AND (surface = 'game'::text) AND (target = ANY (ARRAY['classic'::text, 'induckup'::text, 'survival'::text, 'campus'::text, 'induck-grow'::text])) AND ((event_type <> 'classic_ranked_start'::text) OR (target = 'classic'::text))))
, false));
